public int active()
{
    int ret;

    ret = next active();

    FormControl ctrl = this.formRun().design().controlName(formControlStr(WMSPickingRegistration, PrintMenuButton));
    WMSPickingRoute wmsPickingRoute = this.cursor();

    if (wmsPickingRoute.transType == InventTransType::Sales)
    {
        ctrl.visible(true);
    }
    else
    {
        ctrl.visible(false);
    }

    return ret;
}
